.__UIV_SCOPE__ .button-group {
  flex-grow: 1;
  margin: auto;
}

.__UIV_SCOPE__ .button-group input[type="radio"] {
  display: none;
}

.__UIV_SCOPE__ .button-group label {
  display: inline-block;
  padding: 10px 20px;
  cursor: pointer;
  border: 1px solid #2b426d;
  background-color: #385c7e;
  color: white;
  border-radius: 15px;
  transition: all ease 0.2s;
  text-align: center;
  flex-grow: 1;
  flex-basis: 0;
  width: 90px;
  font-size: 13px;
  margin: 5px;
  box-shadow: 0px 0px 50px -15px #000000;
}

.__UIV_SCOPE__ .button-group input[type="radio"]:checked + label {
  background-color: white;
  color: #02375a;
  border: 1px solid #2b426d;
}

.__UIV_SCOPE__ fieldset {
  border: 0;
  display: flex;
}
